def compute(vars):
    values = {
        "2013": vars["v1"],
        "2012": vars["v2"],
    }
    maximum_year = max(values, key=values.get)
    maximum_value = values[maximum_year]
    return {
        "value": maximum_value,
        "trace": {
            "values_by_year": values,
            "maximum_year": maximum_year,
            "output_meta": {
                "currency": "USD",
                "scale": "million",
                "unit": None,
            },
        },
    }
